  if(name==='header'){
    const nav=extractBlock(html,'<nav ','nav');
    html=html.replace(nav,()=>nav.replace(/href="(\/[^"#?]*)"/g,(attribute,path)=>path===currentPath ? 'aria-current="page" aria-disabled="true" tabindex="-1"' : attribute));
  }
  return html.replace(/(src|href)="(assets\/[a-z0-9.-]+)(?:\?[^"\s]*)?"/g,(_,attr,path)=>`${attr}="${article?'/':''}${fingerprint(path)}"`);
}

// These names correspond to current, visible components in /ds/.
// Page output, future page composition and DS consume these canonical producers.
export function renderRelatedCases({currentCase='raiffeisen-leasing',idPrefix='more-cases'}={}){
  const current=sitePages.find(page=>page.kind==='article'&&page.id===currentCase);
  if(!current)throw Error('Unknown current case for related cases');
  if(!/^[a-z][a-z0-9-]*$/i.test(idPrefix))throw Error('Related cases prefix must be an HTML identifier');
  const projects=getWorkProjects().filter(project=>project.href&&project.href!==current.route);
  const cards=projects.map(project=>{
    const page=sitePages.find(page=>page.kind==='article'&&page.route===project.href);
    if(!page)throw Error('Related cases require a registered route');
    const caseTitle=JSON.parse(read(page.contentSource)).caseTitle;
    if(!caseTitle)throw Error('Related cases require their actual case title');
    return renderTemplate(read('shared/related-case-card.html').trim(),{
      href:escapeText(page.route),id:escapeText(idPrefix+'-'+page.id),caseId:escapeText(page.id),
      caseTitle:escapeText(caseTitle),
      imageSrc:project.imageSrc,imageSrcset:project.imageSrcset,
      imageSizes:'(max-width: 767px) min(296px, calc((100vw - 48px) / 2)), (max-width: 1023px) and (pointer: coarse) min(296px, calc((100vw - 48px) / 2)), 304px'
    });
  }).join('');
  return absoluteAssets(renderTemplate(read('shared/related-cases.html').trim(),{id:escapeText(idPrefix),currentCase:escapeText(currentCase),cards}));
}

export function renderCaseStudyTitle({title,id='case-study-title'}={}){
  if(!title||typeof title!=='string')throw Error('Case study title is required');
  if(!/^[a-z][a-z0-9-]*$/i.test(id))throw Error('Case study id must be an HTML identifier');
  return renderTemplate(read('shared/case-study-title.html').trim(),{id:escapeText(id),title:escapeText(title)});
}

export function renderComponent(name,options={}){
  switch(name){
    case 'icon':return renderIcon(options.name,options);
    case 'header':return absoluteAssets(renderRegion('header',{article:options.variant==='article',...(options.currentPath!==undefined?{currentPath:options.currentPath}:{})})).replace('href="#selected-works"','href="/#selected-works"');
    case 'footer':return renderRegion('footer',{article:true});
    case 'portrait':return absoluteAssets(extractBlock(renderHomeIntro(),'<div class="portrait"'));
    case 'case-study-title':{
      const page=sitePages.find(page=>page.kind==='article'&&page.id===(options.id||'raiffeisen-leasing'));
      if(!page)throw Error('Unknown company article');
      return renderCaseStudyTitle({title:JSON.parse(read(page.contentSource)).caseTitle});
    }
    case 'company-title':{
      const page=sitePages.find(page=>page.kind==='article'&&page.id===(options.id||'raiffeisen-leasing'));
      if(!page)throw Error('Unknown company article');
      const {title,logo}=JSON.parse(read(page.contentSource));
      return absoluteAssets(renderArticleHeading({title,logo,...options}));
    }
    case 'company-page':{
      const source=sitePages.find(page=>['article','review'].includes(page.kind)&&page.id===(options.id||'raiffeisen-leasing'));
      if(!source)throw Error('Unknown company article');
      const content=JSON.parse(read(source.contentSource));
      const page=renderArticlePage(content);
      if(source.kind==='review')return renderRussianReadingAssets()+extractBlock(page,'<header ','header')+extractBlock(page,'<main ','main')+extractBlock(page,'<footer ','footer');
      return renderRegion('header',{article:true,currentPath:new URL(content.canonical).pathname})+extractBlock(page,'<main ','main')+renderRegion('footer',{article:true});
    }
    case 'about-title':return absoluteAssets(renderArticleHeading(options));
    case 'article-title':return absoluteAssets(renderArticleHeading({title:'404',showAvatar:false,...options}));
    case 'back':{
      if(options.variant==='mobile')return renderBack({variant:'mobile',absolute:true});
      return renderBack({variant:options.variant||'desktop',absolute:true}).replace(' about-desktop-back','');
    }
    case 'navigation-link':return absoluteAssets(extractBlock(renderRegion('header',{currentPath:options.currentPath??'/'}),'<nav ','nav').match(/<a\b[^>]*>About<\/a>/)[0]);
    case 'footer-link':return absoluteAssets(extractBlock(extractBlock(renderRegion('footer'),'<nav class="footer-links"','nav'),'<a href="mailto:','a'));
    case 'photo-gallery':return renderPhotoGallery({assetUrl:path=>'/'+fingerprint(path),variant:options.variant});
    case 'recommendations':return absoluteAssets(renderRecommendations(JSON.parse(read('shared/recommendations.json')),options));
    case 'photo-gallery-footer':return renderPhotoGallery({assetUrl:path=>'/'+fingerprint(path),variant:'footer'});
    case 'about-avatar':return absoluteAssets(renderSized(read('shared/about-avatar.html').trim()));
    case 'article-figure':{
      const source=sitePages.find(page=>page.kind==='article'&&page.id===(options.id||'medesk'));
      if(!source)throw Error('Choose a registered article image');
      const content=JSON.parse(read(source.contentSource));
      const images=content.sections.flatMap(section=>section.blocks||[]).filter(block=>block.type==='image');
      const figure=options.layout==='prose'?images.find(image=>image.layout==='prose'):images.find(image=>image.layout!=='prose');
      return '<div class="about-main" style="padding:0"><div class="about-sections about-prose"><section>'+renderArticleFigure(figure)+'</section></div></div>';
    }
    case 'prose-section':return identifyMarkup('<div class="about-sections about-prose">'+extractBlock(renderAboutMain(),'<section aria-labelledby="design-title"','section')+'</div>',options.idPrefix);
    case 'availability':return absoluteAssets(extractBlock(renderWorkActions({...getWorkProjects()[0],href:null},{idPrefix:options.idPrefix}),'<span class="work-availability"','span'));
    case 'work-logo':return absoluteAssets(renderWorkLogo(options.name||'larixon',{decorative:false}));
    case 'work-section':return absoluteAssets(renderWorkSection(undefined,{idPrefix:options.idPrefix})).replace(/data-src=/g,'src=').replace(/data-srcset=/g,'srcset=');
    case 'work-actions':return absoluteAssets(renderWorkActions(undefined,{idPrefix:options.idPrefix}));
    case 'work-card':{
      const projects=getWorkProjects(),project=options.id?projects.find(project=>project.id===options.id):projects[0];
      if(!project)throw Error(`Unknown current work card: ${options.id}`);
      return absoluteAssets(renderWorkCard(project,{idPrefix:options.idPrefix})).replace(/data-src=/g,'src=').replace(/data-srcset=/g,'srcset=');
    }
    case 'related-cases':return renderRelatedCases({currentCase:options.id||'raiffeisen-leasing',...(options.idPrefix?{idPrefix:options.idPrefix}:{})});
    case 'home-about':return absoluteAssets(renderHomeAbout());
    case 'homepage-intro':return absoluteAssets(renderHomeIntro());
    case 'reading-page':return renderRegion('header',{article:true})+renderAboutMain()+renderRegion('footer',{article:true});
    case 'not-found-page':return renderNotFoundContent();
    case 'brief':return absoluteAssets(renderBrief({theme:options.theme||'light',standalone:true,idPrefix:options.idPrefix}));
    default:throw Error(`Register the new component in shared/library.mjs and the /ds/ catalog: ${name}`);
  }
}

// Structured blocks replace paragraphs only when explicitly supplied. Legacy
// paragraph-only sections retain their exact markup and reading-order output.
function proseBlocks({paragraphs=[],blocks}){
  if(blocks===undefined)return paragraphs.map(text=>({type:'paragraph',text}));
  if(!Array.isArray(blocks))throw Error('Prose blocks must be an array');
  for(const block of blocks){
    if(!block||typeof block!=='object'||!['paragraph','subheading','list','recommendations','image'].includes(block.type))throw Error('Unsupported prose block type');
    if(block.type==='image'){
      renderArticleFigure(block);
    }else if(block.type==='list'){
      if(!Array.isArray(block.items)||!block.items.every(item=>typeof item==='string'||(item&&typeof item==='object'&&typeof item.text==='string'&&(item.strong===undefined||typeof item.strong==='boolean')&&(item.href===undefined||typeof item.href==='string'&&/^https:\/\/[^\s]+$/.test(item.href)))))throw Error('Prose list items must be strings or {text, strong?, href?: https URL}');
    }else if(block.type!=='recommendations'&&typeof block.text!=='string')throw Error('Prose block text must be a string');
  }
  return blocks;
}

export function renderProseSection({title,paragraphs=[],blocks,id:sectionId},index=0,readingOrder=0,{recommendations=null}={}){
  if(!Number.isSafeInteger(readingOrder)||readingOrder<0)readingOrder=0;
  const id=sectionId||`article-section-${index+1}`;
  if(!/^[a-z][a-z0-9-]*$/i.test(id))throw Error('Section id must be an HTML identifier');
  const sectionBlocks=proseBlocks({paragraphs,blocks});
  const inlineRecommendations=sectionBlocks.filter(block=>block.type==='recommendations').length;
  if(inlineRecommendations>1)throw Error('Place article recommendations only once');
  if(inlineRecommendations&&!recommendations)throw Error('Inline recommendations require article recommendations data');
  const headingOrder=readingOrder++;
  const content=sectionBlocks.map(block=>{
    const order=`style="--reading-reveal-order:${readingOrder++}"`;
    if(block.type==='paragraph')return `<p ${order}>${escapeText(block.text)}</p>`;
    if(block.type==='subheading')return `<h3 class="prose-subheading" ${order}>${escapeText(block.text)}</h3>`;
    if(block.type==='image')return renderArticleFigure(block).replace('<figure ',`<figure ${order} `);
    if(block.type==='recommendations')return `<div class="prose-recommendations" ${order}>${absoluteAssets(renderRecommendations(recommendations))}</div>`;
    return `<ul class="prose-list" ${order}>${block.items.map(item=>{
      const text=escapeText(typeof item==='string'?item:item.text);
      const label=typeof item==='object'&&item.strong?`<strong>${text}</strong>`:text;
      return `<li>${typeof item==='object'&&item.href?`<a class="article-source-link" href="${escapeText(item.href)}" target="_blank" rel="noopener noreferrer">${label}</a>`:label}</li>`;
    }).join('')}</ul>`;
  }).join('');
  return `<section aria-labelledby="${id}"><h2 id="${id}" style="--reading-reveal-order:${headingOrder}">${escapeText(title)}</h2>${content}</section>`;
}

// A new work page can use the existing About reading template without a mockup.
// This function creates no files and publishes nothing; the caller owns routing.
export function renderArticlePage({title,description='',canonical,caseTitle=null,intro=[],sections=[],leadWorkId=null,showAvatar=false,logo=null,photoGallery=false,recommendations=null,recommendationsPlacement='before-sections',showRelatedCases=false,lang='en',analytics=true,indexable=true,review=false}){
  if(!title||!canonical)throw Error('Article title and canonical URL are required');
  if(!['en','ru'].includes(lang))throw Error('Unsupported reading language');
  if(review&&(lang!=='ru'||analytics!==false||indexable!==false||showRelatedCases||!new URL(canonical).pathname.startsWith('/work/ru/')))throw Error('Proofreading pages must remain Russian, untracked and non-indexable');
  const beforeSection=recommendationsPlacement&&typeof recommendationsPlacement==='object'?recommendationsPlacement.beforeSection:null;
  if(beforeSection){
    if(Object.keys(recommendationsPlacement).length!==1||typeof beforeSection!=='string'||sections.filter(section=>section.id===beforeSection).length!==1)throw Error('Recommendations require one matching beforeSection');
    if(!recommendations)throw Error('Section placement requires recommendations data');
  }else if(!['before-sections','after-sections'].includes(recommendationsPlacement))throw Error('Unknown article recommendations placement');
  const inlineRecommendations=sections.flatMap(section=>proseBlocks(section)).filter(block=>block.type==='recommendations').length;
  if(inlineRecommendations&&(beforeSection||recommendationsPlacement==='after-sections'))throw Error('Choose inline or explicit recommendations placement');
  if(inlineRecommendations>1)throw Error('Place article recommendations only once');
  if(inlineRecommendations&&!recommendations)throw Error('Inline recommendations require article recommendations data');
  const relatedCase=showRelatedCases?sitePages.find(page=>page.kind==='article'&&page.route===new URL(canonical,'https://dmitryrybalka.com').pathname):null;
  if(showRelatedCases&&!relatedCase)throw Error('Related cases require a registered current article');
  const titleMarkup=renderArticleHeading({title,showAvatar,logo});
  let page=renderReadingDocument({currentPath:new URL(canonical,'https://dmitryrybalka.com').pathname,analytics,indexable});
  page=page.replace(/<title>[\s\S]*?<\/title>/,()=>`<title>${escapeText(title)} — Dmitry Rybalka</title>`)
    .replace(/<meta name="description"[^>]*>/,()=>`<meta name="description" content="${escapeText(description)}">`)
    .replace(/<link rel="canonical"[^>]*>/,()=>`<link rel="canonical" href="${escapeText(canonical)}">`);
  const desktopBack=renderComponent('back').replace('class="ui-back"','class="ui-back about-desktop-back"');
  let readingOrder=0;
  const ordered=markup=>markup.replace(/ style="--reading-reveal-order:\d+"/,'').replace(/^(<[^>]+)>/,`$1 style="--reading-reveal-order:${readingOrder++}">`);
  const sectionGroup=markup=>`<div class="about-sections about-prose${sections.length?' article-sections':''}">${markup}</div>`;
  const sectionsMarkup=()=>{
    const groups=[];let prose=[];
    sections.forEach((section,index)=>{
      if(section.id===beforeSection){
        if(prose.length)groups.push(sectionGroup(prose.join('')));
        prose=[];
        groups.push(ordered(absoluteAssets(renderRecommendations(recommendations))));
      }
      const start=readingOrder;readingOrder+=1+proseBlocks(section).length;
      prose.push(renderProseSection(section,index,start,{recommendations}));
    });
    if(prose.length||!groups.length)groups.push(sectionGroup(prose.join('')));
    return groups.join('');
  };
  const main=`<main class="about-main${caseTitle?' case-study-page':''}${showRelatedCases?' has-related-cases':''}" data-navigation-background>${ordered('<div class="about-title-row">')}${desktopBack}${titleMarkup}</div>${caseTitle?ordered(renderCaseStudyTitle({title:caseTitle})):''}<div class="about-intro about-prose">${intro.map((text,index)=>ordered(`<p>${escapeText(text)}</p>`)+(photoGallery&&index===0?'</div>'+renderComponent('photo-gallery')+'<div class="about-intro about-prose">':'')).join('')}</div>${leadWorkId?ordered('<div class="article-work">')+renderComponent('work-card',{id:leadWorkId})+'</div>':''}${recommendations&&!inlineRecommendations&&recommendationsPlacement==='before-sections'?ordered(absoluteAssets(renderRecommendations(recommendations))):''}${sectionsMarkup()}${recommendations&&recommendationsPlacement==='after-sections'?ordered(absoluteAssets(renderRecommendations(recommendations))):''}${showRelatedCases?ordered(renderRelatedCases({currentCase:relatedCase.id})):''}</main>`;
  page=page.replace(extractBlock(page,'<main ','main'),()=>main.replace('<div class="about-intro about-prose"></div>','')).replace(/ data-node-id="[^"]+"/g,'');
  if(recommendations)page=page.replace('</head>',renderRecommendationAssets()+'</head>');
  if(photoGallery){
    page=page.replace('<body class="about-page"','<body class="about-page photo-page"');
    page=page.replace('</head>',renderPhotoGalleryAssets()+'</head>');
  }
  if(leadWorkId){
    page=page.replace('<link rel="stylesheet" href="/about/',()=>`<link rel="stylesheet" href="/${fingerprint('styles.css')}">\n  <link rel="stylesheet" href="/about/`);
    page=page.replace('</head>',()=>`  <script src="/${fingerprint('assets/project-media.js')}" defer></script>\n</head>`);
  }
  if(lang==='ru')page=page.replace('</head>',renderRussianReadingAssets()+'</head>');
  if(review)page=localizeReviewDocument(page);
  return validateDocumentIds(page,{label:'Article document'});
}

// The live service page and DS specimen share the same reading composition.
// Only the visible main is returned; analytics stay in the route integration.
export function renderNotFoundContent(){
  const document=renderArticlePage({
    title:'404',canonical:'https://dmitryrybalka.com/404/',
    intro:['This page may have moved, or the link may be incorrect.']
  });
  let main=extractBlock(document,'<main ','main');
  const back=renderComponent('back');
  main=main.replace(back.replace('class="ui-back"','class="ui-back about-desktop-back"'),'');
  const titleStart='<div class="about-title-row"';
  if(main.split(titleStart).length!==2)throw Error('404 requires one shared article title row');
  main=main.replace(titleStart,'<div class="not-found-content">'+titleStart);
  const emptySections='<div class="about-sections about-prose"></div>';
  if(main.split(emptySections).length!==2)throw Error('404 requires one empty article sections slot');
  return main.replace(emptySections,`<div class="not-found-actions" style="--reading-reveal-order:2">${back.replace(' data-history-back','').replace('<span>Back</span>','<span>Back to home</span>')}</div></div>`);
}

