// One authored dark palette supplies automatic OS matching and DS-only overrides.
export function renderThemeCSS(source){
  const rules=source.replace(/\/\*[\s\S]*?\*\//g,'');
  const parsed=[...rules.matchAll(/([^{}]+)\{([^{}]*)\}/g)];
  if(!parsed.length||parsed[0][1].trim()!==':root')throw Error('Dark theme requires root tokens');
  const scope=selector=>parsed.map(([,selectors,body])=>selectors.trim().split(',').map(part=>part.trim()===':root'?selector:selector+' '+part.trim()).join(', ')+' {'+body+'}').join('\n');
  return ':root { color-scheme: light; }\n'+scope(':root[data-color-scheme="dark"]')+'\n@media (prefers-color-scheme: dark) {\n'+scope(':root:not([data-color-scheme="light"])')+'\n}\n';
}
export function applyColorSchemeHead(html){
  const cleaned=html.replace(/\s*<meta name="(?:theme-color|color-scheme)"[^>]*>/g,'');
  return cleaned.replace(/(<meta charset="utf-8">)/,'$1\n  <meta name="color-scheme" content="light dark">\n  <meta name="theme-color" content="#FFFFFF" media="(prefers-color-scheme: light)">\n  <meta name="theme-color" content="#171819" media="(prefers-color-scheme: dark)">');
}
export function renderThemeFoundation({light,dark,names}){
  const tokens=[...dark.matchAll(/(--(?:color|border)-[a-z-]+):\s*(#[A-Fa-f0-9]{6})/g)];
  const rows=tokens.map(([,key,value])=>{const baseline=light.match(new RegExp(key+':\\s*(#[A-Fa-f0-9]{6})'))?.[1];if(!baseline)throw Error('Missing light token '+key);return `<tr><th scope="row">${names[key.slice(2)]}<br><code>${key}</code></th><td><span class="ds-theme-swatch" style="background:${baseline}"></span>${baseline}</td><td><span class="ds-theme-swatch" style="background:${value}"></span>${value}</td></tr>`;}).join('');
  return `<section id="themes" class="ds-section"><div class="ds-section-heading"><div><span class="ds-label">FOUNDATION</span><h2>System, light &amp; dark</h2></div><p>The site follows your device theme automatically. Use the toolbar to inspect all components, states and templates in either palette, on desktop or mobile.</p></div><p>System follows device changes live. Light and Dark override only this library and its previews for the current tab session. Switching keeps the selected component state mounted; it never changes the main site preference.</p><p>Both palettes use the same semantic tokens and shared stylesheet. Inverse/footer surfaces retain light foregrounds. Photos, project images and colored logos keep their original pixels. Monochrome control icons adapt; explicit light/dark asset galleries retain their own surfaces.</p><div class="ds-theme-table-wrap"><table class="ds-theme-table"><caption>Shared semantic colors in both themes</caption><thead><tr><th>Token</th><th>Light</th><th>Dark</th></tr></thead><tbody>${rows}</tbody></table></div></section>`;
}

