  ['4440','3f816',694,733,226,288,'Hot-air balloons over Cappadocia','balloons'],
  ['8235','e0372',1483,332,220,293,'Rocky winter landscape','cover'],
  ['7013','ab055',696,1045,227.822,335.737,'Coffee brewing outdoors','coffee'],
  ['7375','e2d31',1485,905,219,323,'Rocky coast and blue sea','coast'],
  ['5146','fd9a1',203,317,293,390,'Paddleboards beside an autumn river','cover'],
  ['5291','fcfe0',519,405,405,304,'Paddleboarding together on a quiet river','cover'],
  ['1561','91b2a',947,189,260,346,'Cycling through an autumn forest','cover'],
  ['3989','50894',1230,432,226,301,'A small collection of everyday objects','cover'],
  ['6332','b355d',947,557,260,346,'A bright yellow interior','cover'],
  ['4632','fddbd',448,733,223.215,328.947,'Paddling on the river under summer clouds','paddle']
];
// Periodic staggered columns preserve every crop ratio and the approved size range.
export function layoutPhotos(){
  const layout=JSON.parse(readFileSync(new URL('./photo-layout.json',import.meta.url),'utf8'));
  if(Object.keys(layout.photos).length!==photos.length)throw Error('Photo geometry is out of date');
  const items=photos.map(p=>{
    const box=layout.photos[p[0]];
    if(!box||![box.x,box.y,box.width,box.height].every(Number.isFinite))throw Error('Missing photo geometry: '+p[0]);
    const scale=box.width/box.referenceWidth;
    if(scale<.8||scale>1.2||Math.abs(scale-box.height/box.referenceHeight)>1e-6)throw Error('Photo size exceeds the approved 20%: '+p[0]);
    if(Math.abs(box.width/box.height-p[4]/p[5])>1e-6)throw Error('Photo crop ratio changed: '+p[0]);
    return [p[0],p[1],box.x,box.y,box.width,box.height,p[6],p[7]];
  });
  return {width:layout.width,height:layout.height,items};
}
export function renderPhotoGallery({assetUrl=path=>'/'+path,variant='default'}={}){
  const layout=layoutPhotos();
  const renditions=JSON.parse(readFileSync(new URL('./photo-renditions.json',import.meta.url),'utf8')).photos;
  const items=layout.items.map(([id,file,x,y,w,h,alt,crop])=>{
    const photo=renditions[id];
    if(!photo?.variants?.length||!Number.isFinite(photo.aspect))throw Error('Missing photo renditions: '+id);
    const srcset=photo.variants.map(v=>`${assetUrl(v.file)} ${v.width}w`).join(', ');
    return `<div class="photo-gallery-card photo-crop-${crop}" data-photo-x="${x}" data-photo-y="${y}" data-photo-width="${w}" data-photo-height="${h}" style="--photo-ratio:${w}/${h}"><div class="photo-gallery-crop"><img src="${assetUrl(photo.variants[0].file)}" data-photo-key="${id}" data-source-ratio="${photo.aspect}" data-photo-srcset="${srcset}" alt="${alt}" width="${Math.round(w)}" height="${Math.round(h)}" loading="lazy" decoding="async" fetchpriority="low" draggable="false"></div></div>`;
  }).join('');
  const fade=variant==='footer'?'<div class="photo-gallery-top-fade" aria-hidden="true"></div>':'';
  return `<section class="photo-gallery${variant==='footer'?' photo-gallery-footer':''}" aria-label="Personal photo gallery"><div class="photo-gallery-field" data-world-width="${layout.width}" data-world-height="${layout.height}" tabindex="0" role="region" aria-label="Infinite photo gallery. Drag or swipe in any direction to explore. Use arrow keys to move; Home to reset.">${items}</div>${fade}</section>`;
}

