// Static source content remains readable even if the optional controller fails.
import {readFileSync} from 'node:fs';
import {parseSharedTokens,pixelToken} from './token-values.mjs';
const avatarSize=pixelToken(parseSharedTokens(readFileSync(new URL('./tokens.css',import.meta.url),'utf8')),'size-recommendation-avatar');
const escape=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const quoteParagraph=(text,continuation,className='')=>`<p${className?` class="${className}"`:''}>${escape(continuation===false?text:text.replace(/\.$/,''))}${continuation===false?'':'<span aria-label="Excerpt continues">…</span>'}</p>`;
export function renderRecommendations(data,{idPrefix='recommendations'}={}){
  if(!/^[a-z][a-z0-9-]*$/i.test(idPrefix))throw Error('Recommendations require a unique HTML id prefix');
  const slides=data.items.map((item,index)=>{
    if(!/^https:\/\/www\.linkedin\.com\/in\/[^/?#]+\/(?:[a-z]{2}\/)?$/.test(item.profile||''))throw Error('Recommendation authors require individual LinkedIn profiles');
    if(item.avatar&&!/^assets\/recommendation-[a-z-]+\.webp$/.test(item.avatar))throw Error('Recommendation avatars must be local assets');
    if(item.companyUrl&&!/^https:\/\/www\.linkedin\.com\/company\/[^/?#]+\/$/.test(item.companyUrl))throw Error('Recommendation companies require LinkedIn URLs');
    // Attribution is editorial context, not a visual change to the carousel.
    // About: shared/recommendations.json owns its independent role/company labels.
    // It has no Then prefix and may explicitly mark a former affiliation with ex-.
    // Project: use project-owned data with attribution: 'then'; role/company must
    // describe the verified position DURING collaboration, not today's employer.
    // Match the actual collaboration/project, not only an employer and date range.
    // Project-owned collaboration metadata records role/source/scope evidence.
    // Render Then [role] at [company]. Never overwrite About data for a project.
    // Keep the shared quote, typography, layout and interaction behavior intact.
    const role=item.roleCompact?`<span class="recommendations-role-full">${escape(item.role)}</span><abbr class="recommendations-role-compact" title="${escape(item.role)}">${escape(item.roleCompact)}</abbr>`:escape(item.role);
    const company=item.company?`<span class="recommendations-at">${data.attribution!=='then'&&item.companyStatus==='former'?', ex-':' at '}</span><a class="recommendations-company" href="${escape(item.companyUrl)}" target="_blank" rel="noopener noreferrer">${escape(item.company)}</a>`:'';
    const quote=item.desktopText?quoteParagraph(item.text,item.hasContinuation,'recommendations-quote-mobile')+quoteParagraph(item.desktopText,item.desktopHasContinuation??item.hasContinuation,'recommendations-quote-desktop'):quoteParagraph(item.text,item.hasContinuation);
    return `<figure class="recommendations-slide" id="${idPrefix}-slide-${index+1}" role="group" aria-roledescription="slide" aria-label="${index+1} of ${data.items.length}">
      <blockquote cite="${escape(item.recommendationUrl||data.source)}">${quote}</blockquote>
      <figcaption>${item.avatar?`<img class="recommendations-avatar" src="/${escape(item.avatar)}" alt="" width="${avatarSize}" height="${avatarSize}" decoding="async" fetchpriority="low">`:''}<div class="recommendations-author"><a class="recommendations-author-name" href="${escape(item.profile)}" target="_blank" rel="noopener noreferrer">${escape(item.name)}</a><span class="recommendations-author-role">${data.attribution==='then'?'<span class="recommendations-at">Then </span>':''}${role}${company}</span></div></figcaption>
    </figure>`;
  }).join('\n');
  const dots=data.items.map((item,index)=>`<button type="button" class="recommendations-dot" aria-label="Show recommendation ${index+1}: ${escape(item.name)}" aria-controls="${idPrefix}-slide-${index+1}"${index===0?' aria-current="true"':''}><span class="recommendations-dot-track"><span class="recommendations-dot-fill"></span></span></button>`).join('');
