    <h2 id="${idPrefix}-title">${escape(data.heading)}</h2>
    <div class="recommendations-slides">${slides}</div>
    <div class="recommendations-controls" hidden><div class="recommendations-dots" role="group" aria-label="Choose a recommendation">${dots}</div></div>
    <span class="recommendations-status" aria-live="polite" aria-atomic="true"></span>
  </section>`;
}

