// Runs in the head, before any header can paint. Waiting for navigation is
// distinct from the accessible no-JavaScript / failed-script fallback.
(() => {
  const root=document.documentElement;
  root.classList.add('navigation-js');
  window.mobileLayout=matchMedia('(max-width: 767px), (max-width: 1023px) and (pointer: coarse)');
  let requestedOpen=false;
  window.mobileNavigationReady=new Promise(resolve=>{window.resolveMobileNavigationReady=resolve;});
  window.releaseMobileNavigation=()=>{
    if(root.dataset.mobileNavReady==='true')return;
    root.classList.add('mobile-navigation-fallback');
    window.resolveMobileNavigationReady(false);
  };
  window.mobileNavigationDeadline=setTimeout(window.releaseMobileNavigation,3000);
  const earlyToggle=event=>{
    if(!window.mobileLayout.matches||root.dataset.mobileNavReady==='true'||!event.target.closest?.('.menu-toggle'))return;
    event.preventDefault();event.stopImmediatePropagation();requestedOpen=!requestedOpen;
