  document.addEventListener('click',earlyToggle,true);
  window.mobileNavigationReady.then(ready=>{
    document.removeEventListener('click',earlyToggle,true);
    if(ready&&requestedOpen&&window.mobileLayout.matches)document.querySelector('.menu-toggle')?.click();
  });
})();

